from html.parser import HTMLParser
from pathlib import Path
import sys,re
class Page(HTMLParser):
 def __init__(self): super().__init__(); self.href=None; self.label=[]; self.body=[]
 def handle_starttag(self,t,a):
  if t=='a': self.href=dict(a).get('href',''); self.label=[]
 def handle_data(self,s):
  s=' '.join(s.split())
  if s and len(s)<300: self.body.append(s)
  if self.href is not None: self.label.append(s)
 def handle_endtag(self,t):
  if t=='a' and self.href is not None:
   s=' '.join(self.label).strip()
   if s and re.search(r'job|locali[sz]|proof|\bQA\b',s+' '+self.href,re.I): print(s[:130],self.href[:170])
   self.href=None
p=Page(); p.feed(Path(sys.argv[1]).read_text())
print([s for s in p.body if re.search(r'no jobs|error|locali[sz]|qualit|sign in|log in',s,re.I)][:25])
